INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('0e7dfccc-77eb-4991-baf3-bfaa5fd33d3f', 'vivre_societe', 'Qu''est-ce que la CMU-C (maintenant CSS) ?', '["Un contrat de travail", "Un diplôme universitaire", "La complémentaire santé solidaire pour les personnes à faibles revenus", "Une assurance auto"]'::jsonb, 2, 'La CSS (ex CMU-C) offre une complémentaire santé gratuite ou à faible coût aux personnes à revenus modestes.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('0edb3760-0c09-4da8-b70d-14962bfed338', 'vivre_societe', 'Quelle est la durée minimale de congé maternité en France ?', '["20 semaines", "12 semaines", "8 semaines", "16 semaines"]'::jsonb, 3, 'Le congé maternité dure au minimum 16 semaines pour un premier ou deuxième enfant.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('0f4b0261-d999-4622-ae0a-f6c1df09d568', 'systeme_institutionnel', 'Qui peut saisir le Conseil constitutionnel pour vérifier la conformité d''une loi ?', '["Tout citoyen", "Uniquement le Président", "Les maires", "Le Président, le Premier ministre, les présidents des assemblées ou 60 députés/sénateurs"]'::jsonb, 3, 'La saisine est possible par le Président, le PM, les présidents des assemblées, ou 60 députés/sénateurs.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('158fc7d8-dc49-41d3-b559-722779da4ce3', 'histoire_geographie', 'Quel roi a révoqué l''Édit de Nantes en 1685 ?', '["Louis XIV", "Louis XVI", "Louis XIII", "Henri IV"]'::jsonb, 0, 'Louis XIV a révoqué l''Édit de Nantes par l''Édit de Fontainebleau en 1685, persécutant les protestants.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('15a9f652-16e7-47dc-a26b-419485343374', 'principes_valeurs', 'Quel article de la Constitution affirme que "la France est une République indivisible, laïque, démocratique et sociale" ?', '["Article 3", "Préambule", "Article 2", "Article 1er"]'::jsonb, 3, 'C''est l''article 1er de la Constitution de 1958 qui définit ces principes fondamentaux.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('18e94941-c947-48b5-aaa6-86d1e8c4db73', 'histoire_geographie', 'Quel est le plus haut sommet de France ?', '["Le Mont Ventoux", "Le Pic du Midi", "Le Puy de Dôme", "Le Mont Blanc"]'::jsonb, 3, 'Le Mont Blanc culmine à 4 808 mètres, c''est le plus haut sommet des Alpes et de France.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('2c77461a-e4b1-4219-a995-7140f1ccd21d', 'systeme_institutionnel', 'Qu''est-ce que la cohabitation ?', '["Quand le Président et le PM sont du même parti", "Quand deux partis forment une coalition", "Quand le Président et le PM sont de bords politiques opposés", "Quand le Sénat et l''Assemblée votent ensemble"]'::jsonb, 2, 'La cohabitation survient quand le Président et la majorité parlementaire sont de camps opposés.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('3a7396a8-049b-4ce7-85ec-8314f32df417', 'droits_devoirs', 'Le secret de la correspondance est-il un droit fondamental en France ?', '["Non", "Oui, protégé par la loi", "Seulement pour le courrier postal", "Seulement pour les fonctionnaires"]'::jsonb, 1, 'Le secret des correspondances est un droit fondamental protégé par la loi et la jurisprudence.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('43e48589-52de-4be5-999c-d23aa0e19470', 'vivre_societe', 'Quel est le numéro d''urgence européen ?', '["15", "17", "911", "112"]'::jsonb, 3, 'Le 112 est le numéro d''urgence européen, accessible dans tous les pays de l''UE.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('45daa59f-73e3-4425-8f30-71259b4d997b', 'principes_valeurs', 'En quelle année la devise "Liberté, Égalité, Fraternité" est-elle devenue officiellement la devise de la République ?', '["1880", "1789", "1905", "1848"]'::jsonb, 3, 'Bien qu''utilisée pendant la Révolution, elle n''est devenue officielle qu''en 1848 sous la IIe République.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('461879eb-78dc-47bb-94b8-c3094099f034', 'principes_valeurs', 'Le Conseil constitutionnel peut-il censurer une loi déjà promulguée ?', '["Non, jamais", "Seulement sur demande du Président", "Oui, via la QPC (Question Prioritaire de Constitutionnalité)", "Seulement pour les lois pénales"]'::jsonb, 2, 'Depuis 2010, la QPC permet à tout justiciable de contester la constitutionnalité d''une loi déjà en vigueur.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('55b852d9-add7-44a0-8eac-03b6918c3940', 'systeme_institutionnel', 'Quel article de la Constitution permet au Président de dissoudre l''Assemblée nationale ?', '["Article 12", "Article 16", "Article 49", "Article 5"]'::jsonb, 0, 'L''article 12 donne au Président le pouvoir de dissoudre l''Assemblée nationale.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('6fc9465d-6700-4743-8296-1071a1538780', 'vivre_societe', 'Qu''est-ce que le PACS ?', '["Un pacte civil de solidarité entre deux personnes majeures", "Un acte de propriété", "Un contrat de travail", "Un permis de conduire"]'::jsonb, 0, 'Le PACS (Pacte Civil de Solidarité) est un contrat conclu entre deux personnes majeures pour organiser leur vie commune.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('80f3abdb-7f48-4457-b280-f4521a9cb4b8', 'systeme_institutionnel', 'Quel est le rôle du Conseil d''État ?', '["Juger les affaires pénales", "Voter les lois", "Nommer les ministres", "Conseiller le gouvernement et juger les litiges administratifs"]'::jsonb, 3, 'Le Conseil d''État a un double rôle : conseiller juridique du gouvernement et plus haute juridiction administrative.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('851cf30a-6feb-4bc6-81d8-b3182e433dd8', 'systeme_institutionnel', 'Combien de membres composent le Conseil constitutionnel ?', '["15", "7", "11", "9"]'::jsonb, 3, 'Le Conseil constitutionnel comprend 9 membres nommés, plus les anciens présidents de la République.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('965e230d-e870-45a9-80b9-9cebf988310e', 'histoire_geographie', 'Combien de départements compte la France au total ?', '["96", "110", "101", "105"]'::jsonb, 2, 'La France compte 101 départements : 96 en métropole et 5 outre-mer.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('b91a9389-4a13-48ee-9024-6a86b89a92af', 'principes_valeurs', 'Quelle est la différence entre laïcité et athéisme ?', '["La laïcité interdit la religion, l''athéisme non", "Il n''y a pas de différence", "La laïcité garantit la neutralité de l''État, l''athéisme est l''absence de croyance", "L''athéisme est un principe constitutionnel"]'::jsonb, 2, 'La laïcité est un principe de neutralité de l''État, pas une position sur l''existence de Dieu.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('c7c37714-7385-44c3-a900-645613033297', 'vivre_societe', 'Depuis quelle année le mariage entre personnes de même sexe est-il légal en France ?', '["2015", "2010", "2013", "2017"]'::jsonb, 2, 'Le mariage pour tous a été légalisé en France par la loi du 17 mai 2013.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('cc540e10-4e19-4c57-9e96-06fd67f45bd1', 'droits_devoirs', 'Qu''est-ce que le droit de pétition ?', '["Le droit d''adresser une demande écrite aux autorités publiques", "Le droit de grève", "Le droit de vote", "Le droit de manifester"]'::jsonb, 0, 'Le droit de pétition permet aux citoyens d''adresser des requêtes aux assemblées parlementaires.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d55451e8-9f19-48fa-83bd-a445cff1211e', 'vivre_societe', 'Qu''est-ce que le RSA ?', '["Un diplôme", "Le Revenu de Solidarité Active, une aide financière pour les personnes sans ressources", "Un type de contrat", "Une taxe"]'::jsonb, 1, 'Le RSA assure un revenu minimum aux personnes sans ressources ou avec de très faibles revenus.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d6023d38-0d58-4a9b-bd4c-85d6f9eac8e8', 'droits_devoirs', 'Quelle convention internationale protège les droits de l''enfant ?', '["La Convention de Genève", "La Déclaration universelle des droits de l''homme", "Le traité de Maastricht", "La Convention internationale des droits de l''enfant (1989)"]'::jsonb, 3, 'La Convention internationale des droits de l''enfant, adoptée par l''ONU en 1989, ratifiée par la France en 1990.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d72d8027-5e5d-48b5-9a54-5e521bc4ffc8', 'histoire_geographie', 'Quelle est la population approximative de la France en 2024 ?', '["55 millions", "75 millions", "68 millions", "62 millions"]'::jsonb, 2, 'La France compte environ 68 millions d''habitants en 2024.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d8175973-1978-47e9-b7a5-285c65734acf', 'histoire_geographie', 'Quel événement historique a conduit à la création de la Ve République en 1958 ?', '["La guerre d''Algérie", "La crise de mai 68", "La guerre froide", "La Seconde Guerre mondiale"]'::jsonb, 0, 'La crise politique liée à la guerre d''Algérie a conduit au retour du général de Gaulle et à la création de la Ve République.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('e039ccf9-fb7b-458c-b4d0-cd5cf8fd932e', 'principes_valeurs', 'Quel philosophe des Lumières a défendu la séparation des pouvoirs ?', '["Voltaire", "Rousseau", "Diderot", "Montesquieu"]'::jsonb, 3, 'Montesquieu a théorisé la séparation des pouvoirs dans "De l''esprit des lois" (1748).', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('e426fcd1-b768-49c5-848a-1cad51d7c87d', 'systeme_institutionnel', 'Qu''est-ce que la motion de censure ?', '["Un vote du Sénat", "Un mécanisme permettant à l''Assemblée de renverser le gouvernement", "Une décision du Conseil constitutionnel", "Un vote pour élire le Président"]'::jsonb, 1, 'La motion de censure (article 49-3) permet à l''Assemblée nationale de renverser le gouvernement.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ea03cafa-90d1-4302-b39f-ed22725d8c87', 'droits_devoirs', 'La double nationalité est-elle autorisée en France ?', '["Oui, la France l''accepte", "Seulement pour les personnes nées en France", "Seulement avec les pays de l''UE", "Non, elle est interdite"]'::jsonb, 0, 'La France reconnaît la double nationalité sans restriction de pays.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ea1ca78c-348c-456a-8842-679457f222da', 'systeme_institutionnel', 'Quel est le rôle du Défenseur des droits ?', '["Juger les criminels", "Voter les lois", "Diriger la police", "Protéger les droits et libertés des citoyens face à l''administration"]'::jsonb, 3, 'Le Défenseur des droits est une autorité indépendante qui veille au respect des droits des citoyens.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('f90a2581-49c0-433f-a22f-be5a0077731a', 'histoire_geographie', 'En quelle année le traité de Rome a-t-il été signé, fondant la CEE ?', '["1968", "1962", "1951", "1957"]'::jsonb, 3, 'Le traité de Rome a été signé en 1957, créant la Communauté économique européenne (CEE).', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('fea05159-4d50-4551-aef6-1ca0a24af8a1', 'droits_devoirs', 'Qu''est-ce que le référendum ?', '["Une consultation directe des citoyens sur un projet de loi", "Un sondage d''opinion", "Un vote au Parlement", "Un vote pour élire le Président"]'::jsonb, 0, 'Le référendum permet au peuple de se prononcer directement sur un projet de loi ou une révision constitutionnelle.', 'difficile', '2026-02-10 16:10:34.081432+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('0a03a344-3955-4597-91cb-7dddf29bc697', 'vivre_societe', 'Qu''est-ce que le PACS ?', '["Un Pacte Civil de Solidarité entre deux personnes majeures", "Un contrat de travail", "Un programme d''aide sociale", "Un permis de conduire"]'::jsonb, 0, 'Le PACS (1999) est un contrat entre deux personnes majeures organisant leur vie commune, avec des droits et obligations.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('0a226d7e-8e9f-42a1-9d84-d3229237d255', 'principes_valeurs', 'Quel est le sens juridique du mot "indivisible" dans "République indivisible" ?', '["Égalité des sexes", "Interdiction des partis séparatistes", "Aucune religion d''État", "Une seule souveraineté sur tout le territoire"]'::jsonb, 3, 'L''indivisibilité signifie une seule souveraineté nationale s''exerçant uniformément sur l''ensemble du territoire.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('1116c4a0-aac5-4949-b7d8-08cde28c11dc', 'systeme_institutionnel', 'Quelle est la durée du mandat d''un sénateur ?', '["5 ans", "9 ans", "6 ans", "4 ans"]'::jsonb, 2, 'Les sénateurs sont élus pour un mandat de 6 ans, renouvelés par moitié tous les 3 ans.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('18c702c5-da6e-44a5-a153-908ad1da985c', 'histoire_geographie', 'Quel événement historique est à l''origine de la création du Conseil de l''Europe en 1949 ?', '["La Première Guerre mondiale", "La Seconde Guerre mondiale", "La guerre froide", "La Révolution française"]'::jsonb, 1, 'Le Conseil de l''Europe a été créé en 1949 après la Seconde Guerre mondiale pour promouvoir la démocratie et les droits de l''homme.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('22215df6-2b7a-4d35-ad7b-e900a64ed234', 'principes_valeurs', 'La Charte de l''environnement a été intégrée au bloc de constitutionnalité en quelle année ?', '["2010", "2008", "2004", "2000"]'::jsonb, 2, 'La Charte de l''environnement a été adossée à la Constitution en 2004 et promulguée en 2005.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('288171ba-41e6-4fc3-abdf-e61c34b9c178', 'vivre_societe', 'Quel organisme gère les allocations familiales en France ?', '["L''URSSAF", "La CPAM", "Pôle emploi", "La CAF (Caisse d''Allocations Familiales)"]'::jsonb, 3, 'La CAF gère les prestations familiales et sociales : allocations familiales, APL, RSA, etc.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('307fea29-0bc6-45bc-bf08-e9ff026563f5', 'histoire_geographie', 'En quelle année l''esclavage a-t-il été définitivement aboli en France ?', '["1802", "1870", "1794", "1848"]'::jsonb, 3, 'L''esclavage a été définitivement aboli en France par le décret du 27 avril 1848, sous l''impulsion de Victor Schœlcher.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('318d8955-fb60-49ed-861a-22fae10a7ad8', 'vivre_societe', 'Qu''est-ce que le RSA (Revenu de Solidarité Active) ?', '["Une prestation sociale pour les personnes sans ressources suffisantes", "Une prime d''embauche", "Un crédit immobilier", "Un impôt"]'::jsonb, 0, 'Le RSA est une prestation sociale versée aux personnes ayant de faibles revenus pour leur assurer un minimum de ressources.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('357be198-4dd7-48a0-91a3-0537e9b998ab', 'droits_devoirs', 'Quel traité européen a instauré la citoyenneté européenne ?', '["Le traité de Rome (1957)", "Le traité de Lisbonne (2007)", "Le traité de Nice (2001)", "Le traité de Maastricht (1992)"]'::jsonb, 3, 'Le traité de Maastricht (1992) a instauré la citoyenneté européenne, accordant des droits spécifiques aux citoyens de l''UE.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('37d7ed05-46d5-46ad-964f-84a37ffeb0a7', 'principes_valeurs', 'Quel philosophe des Lumières a particulièrement défendu la tolérance religieuse en France ?', '["Voltaire", "Diderot", "D''Alembert", "Montesquieu"]'::jsonb, 0, 'Voltaire, notamment dans son Traité sur la tolérance (1763), a été un ardent défenseur de la tolérance religieuse.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('48f37657-dab3-4298-be3f-8a8b4d141fb1', 'systeme_institutionnel', 'Qu''est-ce que l''article 49-3 de la Constitution ?', '["L''engagement de responsabilité du gouvernement sur un texte", "La révision constitutionnelle", "Le droit de dissolution", "Le référendum"]'::jsonb, 0, 'L''article 49-3 permet au Premier ministre d''engager la responsabilité du gouvernement pour faire adopter un texte sans vote.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('4ba04e7a-99f5-42dd-a327-accbb9d65568', 'vivre_societe', 'À partir de quel âge la formation est-elle obligatoire en France (formation ou activité) ?', '["Jusqu''à 18 ans", "Jusqu''à 16 ans", "Jusqu''à 21 ans", "Jusqu''à 25 ans"]'::jsonb, 0, 'Depuis 2020, l''obligation de formation est étendue jusqu''à 18 ans : tout jeune de 16 à 18 ans doit être en formation, emploi ou accompagnement.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('6c5776a3-6b8c-4541-9641-750ee9eaf00e', 'histoire_geographie', 'Quelle est la population approximative de la France en 2024 ?', '["75 millions", "62 millions", "68 millions", "55 millions"]'::jsonb, 2, 'La France compte environ 68 millions d''habitants en 2024.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('738c8e8f-00c7-4ec7-b86c-9a5dcf37a41c', 'vivre_societe', 'Qu''est-ce que le CPF (Compte Personnel de Formation) ?', '["Un certificat professionnel", "Un dispositif permettant de financer des formations tout au long de la vie", "Un contrat de travail", "Un compte bancaire"]'::jsonb, 1, 'Le CPF permet à chaque actif de cumuler des droits à la formation utilisables tout au long de sa carrière professionnelle.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('83a848be-0210-4162-b143-99195ba29159', 'principes_valeurs', 'En quelle année le principe de laïcité a-t-il été inscrit dans la Constitution française ?', '["1946", "2004", "1905", "1958"]'::jsonb, 0, 'Le principe de laïcité a été inscrit dans la Constitution en 1946, dans le préambule de la IVe République.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('a03195af-d177-41bb-ba1f-a69ed8cf057f', 'histoire_geographie', 'En quelle année le Code civil (Code Napoléon) a-t-il été promulgué ?', '["1799", "1789", "1815", "1804"]'::jsonb, 3, 'Le Code civil a été promulgué en 1804 sous Napoléon Bonaparte.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('a962306b-af27-470e-a087-8db64cb026ab', 'droits_devoirs', 'La CEDH (Convention européenne des droits de l''homme) a été signée en quelle année ?', '["1992", "1950", "1957", "1948"]'::jsonb, 1, 'La Convention européenne des droits de l''homme a été signée à Rome en 1950 dans le cadre du Conseil de l''Europe.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ad8ede27-0523-4029-bb7e-c201233f74fb', 'vivre_societe', 'Qu''est-ce que la CMU-C (devenue Complémentaire santé solidaire) ?', '["Une couverture santé gratuite pour les personnes à faibles revenus", "Un abonnement médical", "Une mutuelle d''entreprise", "Une assurance auto"]'::jsonb, 0, 'La Complémentaire santé solidaire (ex CMU-C) offre une couverture santé gratuite ou à faible coût aux personnes à revenus modestes.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('afd5da6f-5b70-419b-9d38-089824c6fdaf', 'droits_devoirs', 'Qu''est-ce que le droit au logement opposable (DALO) ?', '["Le droit de sous-louer", "Un droit de propriété", "Le droit de recourir à l''État si on ne trouve pas de logement décent", "Une aide financière au logement"]'::jsonb, 2, 'Le DALO (2007) permet aux personnes mal logées de faire valoir leur droit à un logement devant une commission.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('b306a3c9-3fcd-4cd2-8176-f98534426908', 'systeme_institutionnel', 'Combien de membres compte le Conseil constitutionnel (hors membres de droit) ?', '["12", "7", "9", "5"]'::jsonb, 2, 'Le Conseil constitutionnel est composé de 9 membres nommés, plus les anciens Présidents de la République (membres de droit).', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('b3976b40-d751-4cd7-8775-5fb2308db61d', 'droits_devoirs', 'Qu''est-ce que le Contrôleur général des lieux de privation de liberté ?', '["Le directeur des prisons", "Un juge d''instruction", "Une autorité indépendante veillant aux droits des personnes détenues", "Un avocat commis d''office"]'::jsonb, 2, 'Le CGLPL est une autorité indépendante chargée de veiller au respect des droits fondamentaux des personnes privées de liberté.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d308df06-0f78-4627-a9d6-f75d34373a40', 'principes_valeurs', 'Quel article de la Constitution définit la France comme une République indivisible, laïque, démocratique et sociale ?', '["Article 3", "Article 1er", "Article 5", "Article 2"]'::jsonb, 1, 'L''article 1er de la Constitution de 1958 définit la France comme une République indivisible, laïque, démocratique et sociale.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('dc25b4dd-9431-4da5-8234-779f7470c026', 'histoire_geographie', 'Quel territoire français d''outre-mer est situé dans l''océan Indien ?', '["La Guadeloupe", "La Polynésie française", "La Réunion", "Saint-Pierre-et-Miquelon"]'::jsonb, 2, 'La Réunion est un département français d''outre-mer situé dans l''océan Indien.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('dd06c9e8-b3d0-417e-8952-e90e7cdf56eb', 'droits_devoirs', 'À partir de quel âge un mineur peut-il être entendu par un juge dans une procédure le concernant ?', '["16 ans", "Dès qu''il est capable de discernement", "13 ans", "10 ans"]'::jsonb, 1, 'Un mineur capable de discernement peut être entendu par un juge dans toute procédure le concernant, sans condition d''âge fixe.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('df924746-43eb-4a79-8fea-75b114d9c8a6', 'systeme_institutionnel', 'Quel est le rôle du Défenseur des droits ?', '["Diriger la police", "Voter les lois", "Nommer les juges", "Veiller au respect des droits et libertés par les administrations"]'::jsonb, 3, 'Le Défenseur des droits est une autorité indépendante qui veille au respect des droits des usagers des services publics.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('e4ec9bba-d7fb-43f2-9b3a-95f3201ba556', 'systeme_institutionnel', 'Quelle institution est la plus haute juridiction de l''ordre administratif ?', '["Le Conseil d''État", "Le Tribunal administratif", "La Cour des comptes", "La Cour de cassation"]'::jsonb, 0, 'Le Conseil d''État est la plus haute juridiction de l''ordre administratif en France.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ed707234-2d45-4c22-b634-fa176b26ac9d', 'systeme_institutionnel', 'Qui peut saisir le Conseil constitutionnel pour un contrôle de constitutionnalité a priori ?', '["Tout citoyen", "Les juges uniquement", "Le Président, le PM, les présidents des assemblées ou 60 parlementaires", "Les syndicats"]'::jsonb, 2, 'Le Conseil constitutionnel peut être saisi par le Président, le Premier ministre, les présidents des deux assemblées ou 60 députés/sénateurs.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('fe171de5-13b8-438e-8a26-066e210d580e', 'histoire_geographie', 'Quel est le plus haut sommet de France métropolitaine ?', '["Le Mont Ventoux", "Le Puy de Sancy", "Le Pic du Midi", "Le Mont Blanc"]'::jsonb, 3, 'Le Mont Blanc, culminant à 4 808 mètres, est le plus haut sommet de France et des Alpes.', 'difficile', '2026-02-10 16:25:07.721872+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('051937ae-12c2-4675-99e7-24844973655e', 'vivre_societe', 'La solidarité nationale en France se manifeste principalement par :', '["Les associations caritatives", "Les entreprises privées", "Le système de protection sociale (Sécurité sociale)", "Les dons privés uniquement"]'::jsonb, 2, 'La Sécurité sociale, créée en 1945, est l''expression de la solidarité nationale : chacun contribue selon ses moyens et reçoit selon ses besoins.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('0c67f332-a4a7-4359-84c0-39c6462d172f', 'vivre_societe', 'Quel fromage français à pâte molle est originaire de Normandie ?', '["Le Camembert", "Le Comté", "Le Reblochon", "Le Roquefort"]'::jsonb, 0, 'Le Camembert est un fromage à pâte molle originaire de Normandie, créé selon la légende en 1791.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('124c4a4a-5a8c-4597-bec6-327853b37452', 'histoire_geographie', 'Quel roi de France a signé l''Édit de Nantes en 1598 ?', '["François Ier", "Louis XVI", "Henri IV", "Louis XIV"]'::jsonb, 2, 'Henri IV a signé l''Édit de Nantes en 1598, accordant la liberté de culte aux protestants.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('29e296e4-daed-4ee4-b29f-a768a84c2c08', 'histoire_geographie', 'Quel roi est surnommé le "Roi-Soleil" ?', '["Louis XIII", "Louis XV", "Louis XIV", "Henri IV"]'::jsonb, 2, 'Louis XIV (1643-1715) est le Roi-Soleil, symbole de la monarchie absolue. Il a fait construire le château de Versailles.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('2ac24635-dfd3-42cd-9eb8-fdca5935a0fc', 'principes_valeurs', 'Quel principe républicain interdit toute discrimination fondée sur l''origine ?', '["La laïcité", "La fraternité", "L''égalité", "La liberté"]'::jsonb, 2, 'Le principe d''égalité interdit toute discrimination fondée sur l''origine, la race, le sexe ou la religion.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('3640bfe6-1077-445e-a5de-64de19bb94ff', 'droits_devoirs', 'En quelle année le suffrage universel masculin a-t-il été définitivement instauré en France ?', '["1789", "1944", "1870", "1848"]'::jsonb, 3, 'Le suffrage universel masculin a été définitivement instauré en 1848 sous la IIe République.', 'difficile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('463c5b23-05f1-4732-abd5-1f4a9f869667', 'droits_devoirs', 'Quelle est la différence entre suffrage universel direct et indirect ?', '["Direct : vote en personne ; indirect : vote par courrier", "Direct : les citoyens votent eux-mêmes ; indirect : ils élisent des représentants qui votent", "Direct : pour le président ; indirect : pour le maire", "Il n''y a aucune différence"]'::jsonb, 1, 'Au suffrage direct, les citoyens élisent directement (ex: président). Au suffrage indirect, ils élisent des grands électeurs qui votent (ex: sénateurs).', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('48fe5195-40c8-4a5a-9935-9904f735eb08', 'histoire_geographie', 'Dans quel océan se jette la Loire ?', '["L''océan Atlantique", "La mer Méditerranée", "La mer du Nord", "La Manche"]'::jsonb, 0, 'La Loire se jette dans l''océan Atlantique à Saint-Nazaire.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('5598efe0-78ce-408e-93f1-19a07e1ed4f2', 'histoire_geographie', 'Quelle ville est traversée par la Garonne ?', '["Lille", "Strasbourg", "Toulouse", "Lyon"]'::jsonb, 2, 'La Garonne traverse notamment Toulouse et Bordeaux.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('585f329f-917c-47a1-bb1b-1dee5d439fbc', 'histoire_geographie', 'Qui a été le premier roi des Francs à se convertir au christianisme ?', '["Hugues Capet", "Clovis", "Charlemagne", "Saint Louis"]'::jsonb, 1, 'Clovis Ier s''est fait baptiser vers 496 à Reims, marquant la christianisation du royaume franc.', 'difficile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('61c87917-fde7-496f-8162-d2541c0bb972', 'histoire_geographie', 'Dans quelle mer se jette le Rhône ?', '["La mer du Nord", "La mer Méditerranée", "L''océan Atlantique", "La Manche"]'::jsonb, 1, 'Le Rhône se jette dans la mer Méditerranée, dans la région de Camargue.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('66ca01eb-2eb1-4f99-b6fe-2fa9eca3b0d4', 'principes_valeurs', 'Le Conseil constitutionnel a reconnu la fraternité comme principe à valeur constitutionnelle en :', '["2005", "2018", "1789", "1958"]'::jsonb, 1, 'En 2018, le Conseil constitutionnel a consacré la fraternité comme principe constitutionnel, notamment le droit d''aider autrui dans un but humanitaire.', 'difficile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('71147a74-9152-41b3-bd29-14576e1e7706', 'histoire_geographie', 'Qui a écrit "Les Misérables" ?', '["Gustave Flaubert", "Alexandre Dumas", "Victor Hugo", "Émile Zola"]'::jsonb, 2, 'Victor Hugo a écrit Les Misérables (1862), un roman majeur de la littérature française.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('92a8e082-91a8-4924-b913-c098e6ea52e3', 'histoire_geographie', 'Qui a écrit les fables "Le Corbeau et le Renard" et "La Cigale et la Fourmi" ?', '["Jean de La Fontaine", "Molière", "Voltaire", "Racine"]'::jsonb, 0, 'Jean de La Fontaine (1621-1695) est célèbre pour ses Fables, inspirées d''Ésope.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('a05e87fd-fe4b-4c51-b3de-2952d8957101', 'principes_valeurs', 'La fraternité implique :', '["L''appartenance à une même famille", "La solidarité entre les citoyens", "Le service militaire", "L''obligation de donner de l''argent"]'::jsonb, 1, 'La fraternité est le principe de solidarité entre les citoyens, fondement de la protection sociale et de l''entraide.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ba0ac4ff-ad36-44b8-9e1e-c926cd80e65a', 'principes_valeurs', 'La liberté d''association est garantie par quelle loi ?', '["La loi de 1789", "La loi de 1901", "La loi de 1905", "La loi de 1958"]'::jsonb, 1, 'La loi de 1901 garantit la liberté d''association, permettant à toute personne de créer ou rejoindre une association.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('cb188c18-cc86-4ffb-ae37-73359da26376', 'droits_devoirs', 'Qu''est-ce que le suffrage universel ?', '["Le droit de vote accordé à tous les citoyens majeurs", "Le vote obligatoire", "Le vote par correspondance", "Le vote réservé aux riches"]'::jsonb, 0, 'Le suffrage universel est le droit de vote accordé à tous les citoyens majeurs, sans condition de fortune, de sexe ou d''instruction.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d100acae-e2db-4067-9ecd-9205b479b3e7', 'histoire_geographie', 'Quel écrivain français est l''auteur du "Petit Prince" ?', '["Marcel Proust", "Albert Camus", "Jean-Paul Sartre", "Antoine de Saint-Exupéry"]'::jsonb, 3, 'Antoine de Saint-Exupéry a écrit Le Petit Prince (1943), le livre français le plus traduit au monde.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d33ac072-2c56-40ce-84e2-1ffb6289bf05', 'histoire_geographie', 'Quel fleuve forme une partie de la frontière entre la France et l''Allemagne ?', '["La Seine", "Le Rhône", "Le Rhin", "La Loire"]'::jsonb, 2, 'Le Rhin forme la frontière naturelle entre la France (Alsace) et l''Allemagne.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d44360ec-1b3e-4f06-b829-f7fb1a4e6b84', 'vivre_societe', 'Que signifie l''appellation AOP pour un fromage ?', '["Association des Producteurs", "Attestation Officielle de Production", "Appellation d''Origine Protégée", "Aliment d''Origine Populaire"]'::jsonb, 2, 'L''AOP (Appellation d''Origine Protégée) garantit qu''un produit est fabriqué selon un savoir-faire traditionnel dans une zone géographique définie.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d7306f4b-75e1-4760-b737-795462ea28b9', 'histoire_geographie', 'Quel est le deuxième plus long fleuve de France ?', '["La Garonne", "Le Rhône", "La Seine", "Le Rhin"]'::jsonb, 1, 'Le Rhône (812 km) est le deuxième plus long fleuve de France après la Loire.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d83bbbf2-3308-4975-9161-edd2cde13c51', 'principes_valeurs', 'Quel organisme veille à l''égalité de traitement en France ?', '["La Cour de cassation", "Le Premier ministre", "Le Conseil d''État", "Le Défenseur des droits"]'::jsonb, 3, 'Le Défenseur des droits est une autorité indépendante chargée de lutter contre les discriminations et de défendre les droits des citoyens.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d95ea213-536b-4a34-bd71-ed4ad55e08b3', 'vivre_societe', 'Le Roquefort est fabriqué à partir de quel lait ?', '["Lait de chèvre", "Lait de vache", "Lait de bufflonne", "Lait de brebis"]'::jsonb, 3, 'Le Roquefort est un fromage à pâte persillée fabriqué exclusivement à partir de lait de brebis, affiné dans les caves de Roquefort-sur-Soulzon.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('eaee51cc-5344-44b8-a402-6f9e116480a5', 'histoire_geographie', 'Quel roi a fait construire le château de Versailles ?', '["François Ier", "Henri IV", "Napoléon", "Louis XIV"]'::jsonb, 3, 'Louis XIV a transformé Versailles en résidence royale et siège du pouvoir à partir de 1682.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('f6048bbb-00a7-447e-81d6-2c03e63ab980', 'droits_devoirs', 'La liberté de la presse en France est garantie par quelle loi ?', '["La loi de 1958", "La loi de 1881", "La loi de 1789", "La loi de 1905"]'::jsonb, 1, 'La loi du 29 juillet 1881 sur la liberté de la presse est un texte fondateur garantissant la liberté d''expression et d''information.', 'difficile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('f77d3853-f96f-41b7-b3b1-abdf2835ff66', 'vivre_societe', 'Combien de variétés de fromages la France produit-elle environ ?', '["400", "2 000", "100", "1 200"]'::jsonb, 3, 'La France produit environ 1 200 variétés de fromages différentes, ce qui en fait un élément majeur du patrimoine gastronomique.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('f7b64a18-12dc-4ebd-af44-1f1e6b1b4484', 'histoire_geographie', 'Quel roi a été guillotiné pendant la Révolution française ?', '["Louis XVI", "Louis XV", "Louis XIV", "Charles X"]'::jsonb, 0, 'Louis XVI a été guillotiné le 21 janvier 1793 place de la Révolution à Paris.', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('f8fc0749-9489-4f69-98bf-ca35caba08fc', 'histoire_geographie', 'Quel philosophe français des Lumières a combattu l''intolérance religieuse ?', '["Napoléon", "Descartes", "Voltaire", "De Gaulle"]'::jsonb, 2, 'Voltaire (1694-1778) est un philosophe des Lumières qui a lutté contre l''intolérance, le fanatisme et l''injustice.', 'moyen', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ffbc3058-61f2-4d78-ab4f-154a79ae449f', 'histoire_geographie', 'Molière est célèbre pour avoir écrit des :', '["Poèmes", "Chansons", "Pièces de théâtre", "Romans"]'::jsonb, 2, 'Molière (1622-1673) est le plus grand auteur de comédies de la littérature française (Le Malade imaginaire, L''Avare, Le Misanthrope).', 'facile', '2026-02-12 16:14:01.005618+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('011ed441-61bc-4f62-85a3-c186dbaa632b', 'systeme_institutionnel', 'Quel est l''hymne européen ?', '["L''Internationale", "God Save the Queen", "La Marseillaise", "L''Ode à la Joie de Beethoven"]'::jsonb, 3, 'L''hymne européen est l''Ode à la Joie, tirée de la 9ème symphonie de Beethoven.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('03fb8c84-79c2-451e-83c0-abfdf60c4e41', 'principes_valeurs', 'Depuis quand la laïcité est-elle inscrite dans la Constitution française ?', '["1905", "2004", "1958", "1946"]'::jsonb, 3, 'La laïcité est inscrite dans la Constitution depuis 1946, reprise dans celle de 1958 (article 1er).', 'difficile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('138e15ed-298b-4bc0-b637-f294aceb20ff', 'vivre_societe', 'La mixité est-elle obligatoire dans les écoles publiques ?', '["Seulement au collège", "Oui, depuis 1975", "C''est au choix des parents", "Non, il existe des écoles séparées"]'::jsonb, 1, 'La mixité scolaire est obligatoire dans l''enseignement public depuis la loi Haby de 1975.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('22eb1933-9ebc-4d5f-b36b-6f4ce2269572', 'droits_devoirs', 'Le mariage pour tous est légal en France depuis quelle année ?', '["2017", "2005", "2010", "2013"]'::jsonb, 3, 'La loi du 17 mai 2013 a ouvert le mariage aux couples de personnes de même sexe en France.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('2849b698-2492-49a5-bde8-0b5763c2904f', 'histoire_geographie', 'La France a-t-elle une tradition d''accueil des réfugiés ?', '["Oui, depuis la Révolution française avec le droit d''asile", "Seulement pour les Européens", "Non, c''est récent", "Seulement depuis 1945"]'::jsonb, 0, 'La France a une longue tradition d''accueil, le droit d''asile étant inscrit dès la Constitution de 1793.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('2a77166d-8193-4910-a4ea-b20eb812f8b7', 'principes_valeurs', 'En France, l''État finance-t-il les lieux de culte ?', '["Oui, mais seulement les églises", "Non, jamais en aucun cas", "Oui, tous les lieux de culte", "Non, sauf les édifices construits avant 1905 qui appartiennent à l''État"]'::jsonb, 3, 'Les édifices religieux construits avant 1905 appartiennent souvent à l''État ou aux communes qui les entretiennent.', 'difficile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('38618932-8a92-4c11-acbd-c7f5cf5a011a', 'vivre_societe', 'Jusqu''à quel âge l''instruction est-elle obligatoire en France ?', '["14 ans", "18 ans", "16 ans", "21 ans"]'::jsonb, 2, 'Depuis 2019, l''instruction est obligatoire de 3 à 16 ans, avec une obligation de formation jusqu''à 18 ans.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('5974e65b-190d-4959-a398-2d108d9b91b0', 'droits_devoirs', 'Qu''est-ce que l''OFPRA ?', '["Un organisme de formation", "Une agence pour l''emploi", "Un office du tourisme", "L''Office français de protection des réfugiés et apatrides"]'::jsonb, 3, 'L''OFPRA examine les demandes d''asile et accorde le statut de réfugié en France.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('6f980931-7a09-4840-9e6b-db19516ac00f', 'vivre_societe', 'Quel est le numéro d''urgence pour les pompiers en France ?', '["15", "18", "112", "17"]'::jsonb, 1, 'Le 18 est le numéro des pompiers. Le 15 est le SAMU, le 17 la police, et le 112 le numéro d''urgence européen.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('711f3eac-0e39-4bb0-bbff-2de23f75ad58', 'vivre_societe', 'Qu''est-ce que le CIR (Contrat d''Intégration Républicaine) ?', '["Un contrat signé par les étrangers pour favoriser leur intégration", "Un contrat de location", "Un examen de citoyenneté", "Un contrat de travail"]'::jsonb, 0, 'Le CIR est signé par les étrangers admis au séjour en France. Il inclut des formations civiques et linguistiques.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('75d855be-7f80-4f75-85d2-98c8d5bb869c', 'droits_devoirs', 'Combien d''années de résidence faut-il généralement pour demander la nationalité française ?', '["10 ans", "15 ans", "2 ans", "5 ans"]'::jsonb, 3, 'Il faut généralement 5 ans de résidence régulière en France pour demander la naturalisation.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('77c42ccf-ca87-4a62-acb8-56934bb1436f', 'systeme_institutionnel', 'Combien d''étoiles figurent sur le drapeau européen ?', '["27", "6", "12", "50"]'::jsonb, 2, 'Le drapeau européen comporte 12 étoiles dorées disposées en cercle, symbolisant l''unité et la solidarité.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('79e43b0e-c3d8-4ae8-8255-1a28de07d1d2', 'vivre_societe', 'Quel diplôme obtient-on à la fin du collège ?', '["Le CAP", "Le diplôme national du brevet (DNB)", "Le BTS", "Le baccalauréat"]'::jsonb, 1, 'Le diplôme national du brevet (DNB) est obtenu à la fin de la classe de 3ème (fin du collège).', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('8aabcee1-a8c3-4be6-9fff-94f9d3b44445', 'droits_devoirs', 'À partir de quel âge peut-on se marier en France ?', '["18 ans", "21 ans", "16 ans", "25 ans"]'::jsonb, 0, 'L''âge minimum pour se marier est de 18 ans pour les hommes et les femmes depuis 2006.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('8e274f70-98c5-4958-9f40-24592e005172', 'vivre_societe', 'Le travail dissimulé (travail au noir) est-il légal en France ?', '["Seulement sans contrat écrit", "Seulement pour les petits travaux", "Non, c''est un délit puni par la loi", "Oui, c''est toléré"]'::jsonb, 2, 'Le travail dissimulé est un délit. Tout salarié doit avoir un contrat de travail et être déclaré.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('8f94a699-bed7-4268-b910-86fb13c382c8', 'droits_devoirs', 'Le mariage civil est-il obligatoire en France ?', '["Oui, seul le mariage civil a une valeur légale", "Non, le mariage religieux suffit", "Les deux ont la même valeur", "Seulement pour les étrangers"]'::jsonb, 0, 'En France, seul le mariage civil célébré en mairie a une valeur légale. Le mariage religieux est facultatif et doit être précédé du mariage civil.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('96f97e6a-eeb1-4b2a-925c-d16bfd5e9c4a', 'droits_devoirs', 'Les violences conjugales sont-elles un délit en France ?', '["Oui, elles sont punies par la loi", "Non, c''est une affaire privée", "Seulement les violences physiques", "Seulement si la victime porte plainte"]'::jsonb, 0, 'Les violences conjugales (physiques, psychologiques, sexuelles) sont un délit puni par la loi française.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('9955d8f1-e1b2-498d-a634-e2b98af18cde', 'vivre_societe', 'L''école publique en France est fondée sur quels principes ?', '["Obligation et élitisme", "Gratuité et religion", "Gratuité, laïcité et obligation", "Mixité et sélection"]'::jsonb, 2, 'L''école publique française repose sur trois principes : la gratuité, la laïcité et l''obligation scolaire.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('9fdb37b5-2554-46b2-bdb1-60b87e00701a', 'droits_devoirs', 'Les congés payés existent en France depuis quelle année ?', '["1968", "1900", "1936", "1945"]'::jsonb, 2, 'Les congés payés ont été instaurés en 1936 sous le Front populaire (2 semaines à l''époque).', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('b12e5341-56c4-4074-b52f-e2b633464543', 'principes_valeurs', 'La laïcité garantit-elle le droit de changer de religion ?', '["Oui, la liberté de conscience inclut le droit de changer de religion", "Seulement pour les citoyens français", "Seulement avec l''accord d''un juge", "Non, on doit garder sa religion de naissance"]'::jsonb, 0, 'La laïcité garantit la liberté de conscience, y compris le droit de croire, de ne pas croire et de changer de religion.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('b962ff1d-82b2-48d6-b984-3564067a1e0a', 'systeme_institutionnel', 'Quel traité a créé l''Union européenne sous ce nom ?', '["Le traité de Rome", "Le traité de Lisbonne", "Le traité de Versailles", "Le traité de Maastricht"]'::jsonb, 3, 'Le traité de Maastricht (1992) a créé l''Union européenne et préparé la monnaie unique.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('be5ff955-6dae-4564-8ea2-a62580b4cdbc', 'vivre_societe', 'Qui a rendu l''école primaire gratuite et obligatoire ?', '["Victor Hugo", "Jules Ferry", "Napoléon Bonaparte", "Charles de Gaulle"]'::jsonb, 1, 'Jules Ferry a rendu l''école primaire gratuite (1881) et obligatoire (1882).', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('c6c95afa-46ba-401c-991b-3ebc168ea3eb', 'systeme_institutionnel', 'La France est-elle membre fondateur de la construction européenne ?', '["Oui, depuis le traité de Rome en 1957", "Non, elle a rejoint plus tard", "Seulement depuis 1992", "Seulement depuis l''euro"]'::jsonb, 0, 'La France est l''un des 6 pays fondateurs de la CEE avec le traité de Rome en 1957.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('c83bd072-781b-4b1e-b495-c26c42a57d0c', 'vivre_societe', 'Quel organisme gère l''assurance chômage en France ?', '["La mairie", "La Sécurité sociale", "France Travail (ex-Pôle emploi) et l''Unédic", "La CAF"]'::jsonb, 2, 'France Travail (anciennement Pôle emploi) accompagne les demandeurs d''emploi. L''Unédic gère le régime d''assurance chômage.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('e68de5c0-bd1b-4185-bb3d-e546509ffc8e', 'systeme_institutionnel', 'Quelle est la monnaie commune de la zone euro ?', '["La livre", "L''euro", "Le franc", "Le dollar"]'::jsonb, 1, 'L''euro est la monnaie commune utilisée par 20 pays de l''Union européenne.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ea28e5c0-4d15-4ed6-89bd-7c94aa396c2e', 'principes_valeurs', 'Que signifie la laïcité dans les services publics ?', '["La préférence pour le christianisme", "La promotion de l''athéisme", "L''interdiction de toute religion", "La neutralité de l''État vis-à-vis des religions"]'::jsonb, 3, 'La laïcité impose la neutralité de l''État : il ne favorise ni ne défavorise aucune religion.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ee0abf64-857d-4ce9-8c79-0cdd20bac8b9', 'vivre_societe', 'Qu''est-ce qu''un syndicat ?', '["Un parti politique", "Une association de défense des intérêts des travailleurs", "Un tribunal du travail", "Une entreprise publique"]'::jsonb, 1, 'Un syndicat est une organisation qui défend les intérêts professionnels des salariés.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('f5a4c9a1-57c5-4a74-876d-3d2baae832f8', 'principes_valeurs', 'Les élèves peuvent-ils porter des signes religieux ostensibles à l''école publique ?', '["Seulement au lycée", "Non, c''est interdit par la loi de 2004", "Seulement avec l''accord du directeur", "Oui, c''est un droit absolu"]'::jsonb, 1, 'La loi du 15 mars 2004 interdit le port de signes religieux ostensibles dans les écoles publiques.', 'moyen', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('fcefd129-f188-4b3b-b39c-25bc2ffc9f55', 'droits_devoirs', 'Qu''est-ce que le PACS ?', '["Un permis de séjour", "Un pacte civil de solidarité entre deux personnes", "Une aide au logement", "Un contrat de travail"]'::jsonb, 1, 'Le PACS (Pacte Civil de Solidarité) est un contrat conclu entre deux personnes majeures pour organiser leur vie commune.', 'facile', '2026-02-12 16:40:55.62223+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('01332b33-a46f-4fe5-bf42-8871d701bc15', 'histoire_geographie', 'Quelle fleur offre-t-on traditionnellement le 1er mai ?', '["La rose", "Le tournesol", "Le muguet", "La tulipe"]'::jsonb, 2, 'Le muguet est la fleur traditionnellement offerte le 1er mai, symbole de bonheur et de porte-bonheur.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('055fbe7e-36c6-4481-ac28-a547a9f139bb', 'droits_devoirs', 'Que célèbre-t-on le 1er mai en France ?', '["La fête nationale", "La fête du Travail", "La fête de la musique", "La victoire de 1945"]'::jsonb, 1, 'Le 1er mai est la fête du Travail, seul jour férié obligatoirement chômé en France. On offre traditionnellement du muguet.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('181fdd1c-08cf-4fb3-bc9d-6307e1ecc4ef', 'histoire_geographie', 'En quelle année le premier TGV a-t-il été mis en service ?', '["1990", "1975", "1981", "2000"]'::jsonb, 2, 'Le premier TGV a été mis en service le 27 septembre 1981 sur la ligne Paris-Lyon.', 'difficile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('1c34efde-7e87-4d50-bfde-5b5b82148a67', 'vivre_societe', 'Le lundi de Pâques est-il un jour férié en France ?', '["Seulement les années paires", "Oui", "Seulement en Alsace", "Non"]'::jsonb, 1, 'Le lundi de Pâques est bien un jour férié en France, au même titre que le jeudi de l''Ascension et le lundi de Pentecôte.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('219bd168-7a4b-4b4c-b3c3-9c7047fa98b6', 'vivre_societe', 'Qu''est-ce que le covoiturage ?', '["Une location de voiture", "Un taxi collectif", "Un bus privé", "Le partage d''un véhicule entre plusieurs passagers pour un trajet commun"]'::jsonb, 3, 'Le covoiturage consiste à partager un véhicule personnel avec d''autres passagers pour un même trajet, réduisant les coûts et l''impact environnemental.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('34055987-ac57-4a89-a9a6-d638792f6b3d', 'vivre_societe', 'Qu''est-ce que le tiers payant ?', '["Payer en trois fois", "Ne pas avancer les frais médicaux", "Une taxe sur les médicaments", "Payer un tiers du prix"]'::jsonb, 1, 'Le tiers payant dispense le patient d''avancer les frais médicaux : l''Assurance maladie paie directement le professionnel de santé.', 'moyen', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('35125c3b-c534-4325-b3d6-eb304d578a80', 'vivre_societe', 'Qu''est-ce que la carte Navigo ?', '["Un permis de conduire", "Une carte d''identité", "Une carte bancaire", "Un titre de transport en Île-de-France"]'::jsonb, 3, 'La carte Navigo est le titre de transport utilisé en Île-de-France pour le métro, bus, RER et tramway.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('37c2f6cc-96f6-4da6-8efd-f69e8f4817c4', 'vivre_societe', 'Qu''est-ce qu''une mutuelle santé ?', '["Une assurance complémentaire qui rembourse ce que l''Assurance maladie ne couvre pas", "Un hôpital", "L''Assurance maladie obligatoire", "Un médecin spécialiste"]'::jsonb, 0, 'La mutuelle est une assurance complémentaire santé qui prend en charge tout ou partie des frais non remboursés par l''Assurance maladie.', 'moyen', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('3e144d9f-7275-4f0a-b6e9-6ca6c1dd6630', 'vivre_societe', 'Qu''est-ce que la carte Vitale ?', '["Une carte bancaire", "Une carte d''identité", "La carte d''assurance maladie", "Une carte de transport"]'::jsonb, 2, 'La carte Vitale est la carte d''assurance maladie qui permet le remboursement des soins en France.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('48a3d5cc-adb8-4543-9672-dd3eeb27d954', 'histoire_geographie', 'Quelle ville française possède le plus ancien métro ?', '["Toulouse", "Marseille", "Lyon", "Paris"]'::jsonb, 3, 'Le métro de Paris est le plus ancien de France, inauguré en 1900 pour l''Exposition universelle.', 'moyen', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('61712d36-789f-4fc1-94fb-9bffb1b93c5e', 'vivre_societe', 'Quel est le réseau de trains régionaux en France ?', '["Le TGV", "Le RER", "Le TER", "Le Transilien"]'::jsonb, 2, 'Le TER (Transport Express Régional) est le réseau de trains qui dessert les régions françaises.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('7445f198-4d2b-4e0f-88de-625ae0f86a99', 'vivre_societe', 'Le 25 décembre est un jour férié en France. Que célèbre-t-il ?', '["Noël", "La Saint-Sylvestre", "L''Épiphanie", "Le Nouvel An"]'::jsonb, 0, 'Le 25 décembre (Noël) est un jour férié en France, célébré comme fête familiale et religieuse.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('7f2f832d-46fb-4579-bd7d-0b167995f74f', 'vivre_societe', 'Qu''est-ce que la CMU (devenue CSS) ?', '["La Complémentaire Santé Solidaire pour les personnes à faibles revenus", "Un diplôme médical", "Une mutuelle privée", "Un hôpital public"]'::jsonb, 0, 'La CSS (Complémentaire Santé Solidaire, ex-CMU-C) permet aux personnes à faibles revenus de bénéficier d''une couverture santé gratuite ou à faible coût.', 'moyen', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('873f84f1-944f-4f7c-8dd1-f49aabd1a44a', 'vivre_societe', 'Quel est le nom du train à grande vitesse français ?', '["Le TER", "Le TGV", "Le Transilien", "L''Eurostar"]'::jsonb, 1, 'Le TGV (Train à Grande Vitesse) est le train rapide français, pouvant atteindre 320 km/h en service commercial.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('8d7fffec-58f0-49c2-a97e-2e8929b8a2f4', 'histoire_geographie', 'La Sécurité sociale a été créée en quelle année ?', '["1968", "1936", "1958", "1945"]'::jsonb, 3, 'La Sécurité sociale a été créée en 1945 pour protéger les citoyens contre les risques maladie, vieillesse, accidents du travail et charges familiales.', 'moyen', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ac4a45af-d15b-48da-a6e7-bf8fe1b4d6d3', 'vivre_societe', 'Combien de lignes de métro compte Paris ?', '["16", "10", "20", "14"]'::jsonb, 3, 'Le métro de Paris compte 14 lignes numérotées de 1 à 14, couvrant plus de 200 km.', 'moyen', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('aee7a83c-cc1f-4b7e-88fa-cab907ba3e18', 'vivre_societe', 'Le 1er janvier est un jour férié. Comment appelle-t-on cette fête ?', '["Noël", "Le Jour de l''An", "La Chandeleur", "L''Épiphanie"]'::jsonb, 1, 'Le 1er janvier est le Jour de l''An (Nouvel An), célébrant le début de la nouvelle année.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('af4dc57a-b1cb-4642-9768-a18b1d9be520', 'vivre_societe', 'Combien de jours fériés y a-t-il en France métropolitaine ?', '["13", "8", "11", "15"]'::jsonb, 2, 'La France métropolitaine compte 11 jours fériés par an.', 'moyen', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d9a74d1d-36f5-45c6-a206-d986deee2c77', 'vivre_societe', 'Quel numéro appeler pour le SAMU (urgences médicales) ?', '["18", "112", "15", "17"]'::jsonb, 2, 'Le 15 est le numéro du SAMU (Service d''Aide Médicale Urgente) pour les urgences médicales.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('de77d7e0-33c3-43c5-baa4-cf1115e6082d', 'histoire_geographie', 'Qu''est-ce que la fête de la Musique ?', '["Une fête populaire gratuite le 21 juin", "Un jour férié", "Un concours musical", "Un festival payant"]'::jsonb, 0, 'La fête de la Musique a lieu chaque 21 juin (solstice d''été). Créée en 1982 par Jack Lang, elle permet à tous de jouer de la musique dans les rues.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('e0bc953b-16b0-420e-99e8-5a7a1c1333f4', 'vivre_societe', 'Qu''est-ce que la PMI ?', '["La Protection Maternelle et Infantile", "Un programme immobilier", "Une prime ministérielle", "Un parti politique"]'::jsonb, 0, 'La PMI (Protection Maternelle et Infantile) est un service départemental gratuit de suivi médical pour les femmes enceintes et les enfants de moins de 6 ans.', 'moyen', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ed8f2e69-0ba8-4f64-9b78-b1000c29cc16', 'droits_devoirs', 'Quel document est obligatoire pour conduire en France ?', '["Le passeport", "Le livret de famille", "La carte Vitale", "Le permis de conduire"]'::jsonb, 3, 'Le permis de conduire est obligatoire pour conduire un véhicule motorisé en France.', 'facile', '2026-02-12 18:47:57.742597+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('26c1667c-84a5-4af1-a727-98ee491d66ef', 'systeme_institutionnel', 'Quel est le rôle du pouvoir exécutif ?', '["Juger les criminels", "Voter les lois", "Appliquer et faire respecter la loi", "Contrôler l''application des lois"]'::jsonb, 2, 'Le pouvoir exécutif, exercé par le Gouvernement, applique et fait respecter la loi.', 'facile', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('5619b977-1251-4165-9303-6fc7799fe6fd', 'systeme_institutionnel', 'Que signifie la "primauté du droit" ?', '["Le président est au-dessus des lois", "Les lois ne changent jamais", "Les juges font les lois", "Le droit s''impose à tous, y compris à l''État"]'::jsonb, 3, 'La primauté du droit signifie que le droit s''impose à tous, y compris à l''État et à ses représentants.', 'moyen', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('5e528409-cabb-47ef-b79e-3df7ce4bbf83', 'systeme_institutionnel', 'Un ministre qui ne respecte pas la loi peut-il être sanctionné ?', '["Oui, comme tout citoyen", "Non, les ministres sont au-dessus des lois", "Non, sauf en cas de guerre", "Seulement par le président"]'::jsonb, 0, 'Grâce à la séparation des pouvoirs et à l''État de droit, un ministre qui ne respecte pas la loi peut être sanctionné comme tout citoyen.', 'facile', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('883dc2da-4704-4f75-a641-a2b561e1ec66', 'systeme_institutionnel', 'Que signifie la "sécurité juridique" dans un État de droit ?', '["Les prisons sont surveillées", "La loi est claire et ne change pas constamment", "La police protège les citoyens", "Les frontières sont sécurisées"]'::jsonb, 1, 'La sécurité juridique signifie qu''on peut avoir confiance en la loi : elle est claire et ne change pas tout le temps.', 'difficile', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('94f7f00c-9216-49a0-aaa4-f3dae78add02', 'systeme_institutionnel', 'Combien de principes définissent l''État de droit ?', '["6", "4", "5", "3"]'::jsonb, 0, 'On définit l''État de droit selon 6 principes : primauté du droit, égalité devant la loi, séparation des pouvoirs, légalité, sécurité juridique et protection juridictionnelle effective.', 'difficile', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('9dd0749c-a300-47e8-8471-b6040f152273', 'systeme_institutionnel', 'Pourquoi sépare-t-on les pouvoirs en France ?', '["Pour réduire le nombre de fonctionnaires", "Pour limiter le rôle du Parlement", "Pour garantir les droits fondamentaux et empêcher l''arbitraire", "Pour accélérer le vote des lois"]'::jsonb, 2, 'La séparation des pouvoirs garantit les droits fondamentaux et conserve un équilibre : les pouvoirs se contrôlent mutuellement et ne peuvent s''exercer de façon arbitraire.', 'moyen', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('a99d9da3-1d54-4f5b-8ceb-2c017ba5350f', 'systeme_institutionnel', 'Quel est le contraire de l''État de droit ?', '["L''État arbitraire", "L''État fédéral", "L''État unitaire", "L''État laïque"]'::jsonb, 0, 'L''État de droit est le contraire de l''État arbitraire, car les autorités publiques agissent toujours en respectant la loi.', 'moyen', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('b8673cb7-67f1-4e17-8c88-828103452e70', 'systeme_institutionnel', 'Quel pouvoir est exercé par le Parlement ?', '["Le pouvoir législatif", "Le pouvoir militaire", "Le pouvoir exécutif", "Le pouvoir judiciaire"]'::jsonb, 0, 'Le pouvoir législatif est exercé par le Parlement qui vote les lois.', 'facile', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('b893bab7-850d-417a-9c7a-374111006dcc', 'systeme_institutionnel', 'Dans quel texte est inscrit le principe de séparation des pouvoirs ?', '["La Constitution, qui cite la Déclaration des droits de l''homme de 1789", "La Charte de l''environnement", "Le Code pénal", "Le Code civil"]'::jsonb, 0, 'Le principe de séparation des pouvoirs est inscrit dans la Constitution, qui cite la Déclaration des droits de l''homme et du citoyen de 1789.', 'moyen', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('eb7119ff-1fe4-4f57-9b61-65b90b274771', 'systeme_institutionnel', 'Quels sont les 3 pouvoirs séparés en France ?', '["Législatif, exécutif, judiciaire", "Municipal, régional, national", "Présidentiel, parlementaire, syndical", "Militaire, religieux, économique"]'::jsonb, 0, 'Les trois pouvoirs sont le législatif (le Parlement vote les lois), l''exécutif (le Gouvernement applique la loi) et le judiciaire (contrôle l''application des lois).', 'facile', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('eb8fc804-c856-4289-b9cf-e83a4e2fdc42', 'systeme_institutionnel', 'Qu''est-ce qu''un État de droit ?', '["Un État où le président décide seul", "Un État sans Constitution", "Un système où la loi est la même pour tous, y compris pour l''État", "Un État dirigé par des juges"]'::jsonb, 2, 'Un État de droit est un système dans lequel la loi est la même pour tous, y compris pour l''État. Le droit est supérieur aux pouvoirs et aux autorités politiques.', 'facile', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('f499f56b-3f46-4482-88dd-ef69a14f9257', 'systeme_institutionnel', 'Qui contrôle les autorités publiques dans un État de droit ?', '["L''armée", "Des juges indépendants", "Les partis politiques", "Le président seul"]'::jsonb, 1, 'Dans un État de droit, des juges indépendants contrôlent les autorités publiques.', 'moyen', '2026-02-12 19:20:19.767726+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('105c4cf3-d26a-49f8-b4c8-44721262c413', 'principes_valeurs', 'Un usager d''un service public peut-il porter un signe religieux ?', '["Non, c''est interdit", "Oui, la neutralité ne s''impose pas aux usagers", "Seulement dans certaines régions", "Non, sauf les jours fériés"]'::jsonb, 1, 'La neutralité ne s''impose pas aux personnes qui se rendent dans un service public en tant qu''usagers. Elles peuvent porter un signe religieux.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('1b6d10cc-7556-4dca-bafb-feb1c0634b91', 'vivre_societe', 'Qu''est-ce que la domiciliation ?', '["L''achat d''un logement", "Le fait d''avoir une adresse administrative officielle", "L''inscription à l''école", "L''ouverture d''un compte bancaire"]'::jsonb, 1, 'La domiciliation est une démarche administrative essentielle qui consiste à avoir une adresse officielle pour recevoir son courrier et effectuer ses démarches.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('38f35c9b-e625-4a10-9bc1-36e3f7192fb6', 'vivre_societe', 'Quand a lieu la déclaration annuelle de revenus ?', '["En janvier-février", "En avril-mai", "En septembre-octobre", "En décembre"]'::jsonb, 1, 'La déclaration annuelle de revenus a lieu entre avril et mai de chaque année. On déclare les revenus de l''année précédente.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('4138f983-c949-46b0-901c-7e84bcd8e702', 'droits_devoirs', 'Qu''est-ce que le droit de disposer de son corps ?', '["L''obligation de donner ses organes", "Le droit de refuser tout traitement médical", "La liberté pour chaque personne de faire ses propres choix concernant son corps", "Le droit de choisir son médecin"]'::jsonb, 2, 'Le droit de disposer de son corps est la liberté pour chaque personne de faire elle-même ses propres choix concernant son corps.', 'facile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('414c2ec1-8cef-4f15-b74b-8af2483219bc', 'principes_valeurs', 'Que garantit la laïcité en France ?', '["L''interdiction de toute religion", "La liberté de conscience pour tous", "L''obligation de pratiquer une religion", "La supériorité d''une religion sur les autres"]'::jsonb, 1, 'La laïcité garantit la liberté de conscience : chaque personne est libre d''avoir ou de ne pas avoir de religion, d''en changer ou de ne plus en avoir.', 'facile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('43302013-280f-467b-966c-3dc539fd5043', 'vivre_societe', 'Qu''est-ce que l''assurance responsabilité civile ?', '["Une assurance vie", "Une assurance qui couvre les dommages causés à autrui", "Une assurance auto uniquement", "Une mutuelle santé"]'::jsonb, 1, 'L''assurance responsabilité civile couvre les dommages que vous pouvez causer à d''autres personnes. C''est une démarche importante du quotidien en France.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('469f86b4-5a4b-4df9-8ddd-45402ea28a15', 'systeme_institutionnel', 'Quel est le rôle du préfet ?', '["Diriger la mairie", "Représenter l''État dans le département", "Présider le tribunal", "Commander l''armée locale"]'::jsonb, 1, 'Le préfet est le représentant de l''État dans le département. Il est chargé de veiller à l''application des lois et des décisions du gouvernement.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('51e8829a-1ec1-47e2-a491-2222ee30edaf', 'droits_devoirs', 'Que signifie la dignité humaine ?', '["Le droit de vote", "Le respect inconditionnel de chaque personne simplement parce qu''elle est un être humain", "Le droit au travail", "La liberté d''expression"]'::jsonb, 1, 'La dignité humaine signifie que chaque personne a de la valeur et mérite un respect inconditionnel, peu importe son âge, sexe, condition sociale, religion ou origine.', 'facile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('5930bd77-f27c-4d04-a186-7a16b9b5207e', 'principes_valeurs', 'Quel est le rapport entre l''État français et les religions ?', '["L''État finance toutes les religions équitablement", "L''État reconnaît le christianisme comme religion officielle", "L''État ne reconnaît, ne salarie ni ne subventionne aucun culte", "L''État interdit toutes les pratiques religieuses"]'::jsonb, 2, 'L''État français ne reconnaît aucune religion, ne salarie ni ne subventionne aucun culte, et ne participe pas au fonctionnement des organisations religieuses.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('59f88723-227d-4a56-8614-d82f2517e73f', 'systeme_institutionnel', 'Qu''est-ce que la pluralité des partis politiques ?', '["Un seul parti dirige le pays", "Plusieurs partis peuvent exister et se présenter aux élections", "Les partis doivent fusionner", "Seuls deux partis sont autorisés"]'::jsonb, 1, 'Le principe de pluralité des partis signifie que plusieurs partis politiques peuvent exister, s''exprimer et se présenter aux élections. C''est un pilier de la démocratie.', 'facile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('5e68aeb3-c243-4a33-8f36-7c93f4d945ab', 'principes_valeurs', 'Que signifie la "fraternité" dans la devise française ?', '["L''amour de la patrie", "L''obéissance aux lois", "La solidarité entre les citoyens", "La liberté religieuse"]'::jsonb, 2, 'La fraternité désigne la solidarité entre les citoyens, c''est l''une des trois valeurs fondamentales de la devise républicaine.', 'facile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('782e5c86-d4f3-471e-a4b9-17c46bb714e9', 'vivre_societe', 'Doit-on déclarer ses revenus même si on n''a pas travaillé ?', '["Non, c''est inutile", "Non, seules les personnes actives déclarent", "Oui, il faut indiquer 0 euro", "Seulement si on a plus de 25 ans"]'::jsonb, 2, 'Il est obligatoire de déclarer ses revenus même si on ne travaille pas. Il faut alors indiquer 0 euro.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('7fbc175e-0e00-4450-bfbd-c1034caa9d28', 'principes_valeurs', 'Un usager peut-il demander une adaptation du service public au nom de sa religion ?', '["Oui, c''est un droit fondamental", "Oui, si sa demande est raisonnable", "Non, ce n''est pas possible", "Oui, avec un certificat religieux"]'::jsonb, 2, 'Les usagers ne peuvent pas demander une adaptation du service public au nom d''une religion, même s''ils peuvent porter des signes religieux.', 'difficile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('91bc2126-1007-4a7d-a2fc-3e64f2ff73b5', 'droits_devoirs', 'Le trafic d''organes est-il autorisé en France ?', '["Oui, sous conditions médicales", "Oui, avec le consentement du donneur", "Non, le corps humain ne peut être source de profit", "Oui, uniquement entre membres d''une même famille"]'::jsonb, 2, 'L''article 3 de la Charte des droits fondamentaux de l''UE interdit que le corps humain soit une source de profit. Le trafic d''organes est donc interdit.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('b4df000b-f955-4be0-a767-f73078aa1954', 'droits_devoirs', 'Depuis quelle année l''IVG est-elle légale en France ?', '["1968", "1975", "1981", "1990"]'::jsonb, 1, 'La loi n°75-17 du 17 janvier 1975 (loi Veil) a autorisé l''interruption volontaire de grossesse en France.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('bcc52879-19db-486d-94e6-a9a87680aa57', 'principes_valeurs', 'Depuis quelle année la devise "Liberté, Égalité, Fraternité" est-elle officielle ?', '["1789", "1830", "1848", "1958"]'::jsonb, 2, 'La devise est adoptée officiellement en 1848 sous la 2ème République, bien qu''elle soit apparue pendant la Révolution française de 1789.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('c124994c-e8a3-4f5c-a14d-1a16d1edc9cb', 'principes_valeurs', 'Les agents du service public peuvent-ils porter des signes religieux ?', '["Oui, s''ils sont discrets", "Non, ils doivent respecter le principe de neutralité", "Oui, uniquement le vendredi", "Oui, avec l''accord de leur supérieur"]'::jsonb, 1, 'Les personnes travaillant dans les services publics ne peuvent pas exprimer ou montrer leurs convictions religieuses, politiques ou philosophiques. C''est le principe de neutralité.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('c1312392-1359-4373-bd3d-08d149af8431', 'vivre_societe', 'À quoi servent les impôts en France ?', '["À enrichir les politiciens", "À financer les services publics, aides sociales, routes, écoles...", "Uniquement à l''armée", "À rembourser la dette uniquement"]'::jsonb, 1, 'L''impôt permet à l''État de développer et faire fonctionner les services publics gratuits, les aides sociales, la gestion des routes, etc.', 'facile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('c44f1055-aa38-476f-a1bf-f49e3bdcd6d6', 'principes_valeurs', 'Où peut-on lire la devise de la République française ?', '["Uniquement sur la carte d''identité", "Sur les bâtiments publics, pièces de monnaie, timbres et documents officiels", "Seulement dans la Constitution", "Uniquement lors du 14 juillet"]'::jsonb, 1, 'La devise est visible sur les bâtiments publics (mairies, écoles, tribunaux), certaines pièces de monnaie, timbres, documents officiels et lors de fêtes nationales.', 'facile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('c7931099-a37e-4071-9b6a-e26b17be8280', 'systeme_institutionnel', 'Qu''est-ce que la décentralisation ?', '["Le transfert de compétences de l''État vers les collectivités territoriales", "La centralisation de tous les pouvoirs à Paris", "La suppression des régions", "Le regroupement des communes"]'::jsonb, 0, 'La décentralisation est le transfert de certaines compétences de l''État vers les collectivités territoriales (communes, départements, régions) pour rapprocher les décisions des citoyens.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('c952a033-4489-4b2a-88b2-2cd1ace0c1f1', 'vivre_societe', 'Que risque-t-on si on ne déclare pas ses revenus ?', '["Rien, c''est facultatif", "Des pénalités financières, le remboursement des aides et jusqu''à une peine de prison", "Un simple avertissement", "Une amende de 50 euros"]'::jsonb, 1, 'Ne pas faire sa déclaration peut entraîner des pénalités financières, le remboursement des aides perçues, des difficultés d''accès aux droits et jusqu''à une peine de prison.', 'moyen', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d100449f-861e-4c2c-bc0b-c03a0fe554b9', 'droits_devoirs', 'Jusqu''à quel âge la contraception est-elle prise en charge à 100% par l''Assurance Maladie ?', '["18 ans", "21 ans", "26 ans", "30 ans"]'::jsonb, 2, 'La contraception des femmes assurées sociales de moins de 26 ans est prise en charge par l''Assurance Maladie sans avance de frais.', 'difficile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d2acebf7-9959-484a-8b3d-787027852d89', 'droits_devoirs', 'Dans quel texte européen la dignité humaine est-elle inscrite au chapitre 1 ?', '["Le Traité de Maastricht", "La Convention européenne des droits de l''homme", "La Charte des droits fondamentaux de l''Union européenne de 2000", "Le Traité de Rome"]'::jsonb, 2, 'La dignité humaine est inscrite dans le premier chapitre de la Charte des droits fondamentaux de l''Union européenne de 2000.', 'difficile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('d6531274-4fb7-40ee-8068-590ae8a1cd5b', 'principes_valeurs', 'La laïcité est inscrite dans quel article de la Constitution ?', '["L''article 1er", "L''article 2", "L''article 5", "Le préambule uniquement"]'::jsonb, 0, 'L''article 1er de la Constitution de 1958 précise que "La France est une République indivisible, laïque, démocratique et sociale".', 'difficile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('db421e19-0dc4-4cd2-966e-16ca1dd3cec2', 'vivre_societe', 'Qu''est-ce que la VAE ?', '["La Vérification Administrative d''Emploi", "La Validation des Acquis de l''Expérience", "La Valeur Ajoutée d''Entreprise", "La Visite Annuelle d''Évaluation"]'::jsonb, 1, 'La VAE (Validation des Acquis de l''Expérience) permet d''obtenir un diplôme grâce à son expérience professionnelle, sans reprendre des études.', 'difficile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ec166d06-d672-4243-adb4-28a82faa3904', 'vivre_societe', 'Comment s''appelle l''organisme public d''aide à l''emploi en France ?', '["Pôle Formation", "France Travail", "Emploi France", "Service Emploi National"]'::jsonb, 1, 'France Travail (anciennement Pôle Emploi) est l''organisme public qui aide les personnes à trouver un emploi et les accompagne dans leurs démarches.', 'facile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('f62063d0-1e04-47ff-8b3c-5b71acd8f388', 'vivre_societe', 'Qui doit déclarer ses revenus en France ?', '["Uniquement les personnes qui travaillent", "Toute personne de plus de 18 ans résidant en France", "Uniquement les citoyens français", "Les personnes gagnant plus de 10 000 euros"]'::jsonb, 1, 'Toute personne de plus de 18 ans résidant en France (citoyen français ou pas) doit déclarer ses revenus, même si ses revenus sont nuls.', 'facile', '2026-02-12 19:29:54.98746+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('17af52bc-76ff-4c6a-accd-d23af1c655dc', 'vivre_societe', 'Un collègue vous demande de prier avec lui pendant la pause déjeuner dans un espace commun de l''entreprise. Quelle est la règle ?', '["C''est un droit absolu dans toute entreprise", "L''employeur peut encadrer l''expression religieuse dans le règlement intérieur", "La prière est interdite en France", "Seules certaines religions sont autorisées au travail"]'::jsonb, 1, 'L''employeur peut, via le règlement intérieur, encadrer l''expression des convictions religieuses au travail si cela est justifié par le bon fonctionnement de l''entreprise. La liberté de conscience reste garantie.', 'difficile', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('2fc8e36f-d878-4f0c-8ef2-82b0397eb508', 'droits_devoirs', 'Votre enfant de 5 ans refuse d''aller à l''école. En tant que parent, que devez-vous faire ?', '["Respecter son choix car il est encore petit", "L''obliger à y aller car la scolarité est obligatoire dès 3 ans", "Attendre qu''il ait 6 ans pour l''inscrire", "Demander une dérogation au maire"]'::jsonb, 1, 'En France, l''instruction est obligatoire pour tous les enfants de 3 à 16 ans. Les parents ont le devoir légal d''envoyer leurs enfants à l''école, et des sanctions sont prévues en cas d''absentéisme répété.', 'facile', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('30ffcd89-a9ae-416d-87e8-13d55cc41402', 'vivre_societe', 'Votre voisin fait du bruit avec de la musique forte à 23h en semaine. Que devez-vous faire en premier ?', '["Appeler immédiatement la police", "Faire encore plus de bruit pour qu''il comprenne", "Essayer de dialoguer avec votre voisin pour lui demander de baisser le volume", "Déménager"]'::jsonb, 2, 'En France, le respect du voisinage est une obligation. Les nuisances sonores sont réglementées, notamment la nuit (généralement après 22h). Le dialogue est toujours privilégié en premier lieu avant toute démarche légale ou appel aux autorités.', 'facile', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('3e68f6d6-fcba-4956-958f-c72415b69bfe', 'vivre_societe', 'Votre voisin jette régulièrement ses déchets dans les espaces communs de l''immeuble. Quelle démarche adopter ?', '["Jeter vos déchets devant sa porte en représailles", "En parler d''abord avec lui, puis contacter le syndic ou le bailleur si le problème persiste", "Ne rien faire pour éviter les conflits", "Changer de résidence"]'::jsonb, 1, 'Le respect des parties communes est une obligation pour tous les résidents. La démarche recommandée est d''abord le dialogue, puis le recours au syndic de copropriété ou au bailleur social. En dernier recours, une médiation ou une action en justice est possible.', 'facile', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('455b6981-d752-4e4a-996a-b3cc0300550b', 'vivre_societe', 'Votre employeur dans une entreprise privée vous demande de retirer un signe religieux visible au travail. Que devez-vous faire ?', '["Refuser car c''est une atteinte à votre liberté religieuse", "Accepter si cette restriction est justifiée par la nature de la tâche et proportionnée", "Porter plainte immédiatement pour discrimination", "Démissionner sans discussion"]'::jsonb, 1, 'Dans le secteur privé, l''employeur peut restreindre le port de signes religieux si cela est justifié par la nature de la tâche à accomplir et proportionné au but recherché. La laïcité s''applique différemment dans le secteur public et le secteur privé.', 'moyen', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('46b5f2db-274c-4cc3-ad4f-151dc18fedaf', 'droits_devoirs', 'Vous êtes témoin d''un refus de location d''appartement fondé sur l''origine ethnique du candidat. Que pouvez-vous faire ?', '["Rien, c''est une affaire privée entre le propriétaire et le candidat", "Signaler les faits au Défenseur des droits ou porter plainte car la discrimination est interdite par la loi", "Conseiller au candidat de changer de nom", "Écrire un avis négatif sur internet"]'::jsonb, 1, 'La discrimination fondée sur l''origine est interdite et punie par la loi française (jusqu''à 3 ans d''emprisonnement et 45 000 € d''amende). Vous pouvez signaler les faits au Défenseur des droits ou accompagner la victime pour porter plainte.', 'moyen', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('6c446150-03c8-4da3-b01b-85912cccc9d1', 'droits_devoirs', 'Vous venez de recevoir votre carte électorale pour les élections municipales. Êtes-vous obligé(e) de voter ?', '["Oui, le vote est obligatoire en France", "Non, le vote n''est pas obligatoire mais c''est un devoir civique fortement encouragé", "Oui, sous peine d''amende", "Non, seuls les fonctionnaires doivent voter"]'::jsonb, 1, 'En France, le vote n''est pas obligatoire mais il est considéré comme un devoir civique. Le vote est secret et personnel. Chaque citoyen est encouragé à participer aux élections pour faire vivre la démocratie.', 'facile', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('ace82900-a4e7-4885-97c7-6f0ecdf95531', 'droits_devoirs', 'Votre voisin vous dit qu''il n''envoie pas son enfant de 8 ans à l''école car il préfère l''éduquer à la maison. Est-ce possible ?', '["Non, l''école est obligatoire uniquement dans un établissement scolaire", "Oui, l''instruction à domicile est possible sous conditions strictes et contrôle de l''État", "Oui, sans aucune condition", "Non, c''est un délit puni de prison"]'::jsonb, 1, 'L''instruction en famille est possible mais soumise à des conditions strictes depuis la loi de 2021. Une autorisation préalable est nécessaire et l''État contrôle régulièrement le niveau d''instruction de l''enfant.', 'difficile', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('cc0f5fbd-9029-434a-ac1d-e39a1d3b3112', 'droits_devoirs', 'Le jour de l''élection, vous ne pouvez pas vous rendre au bureau de vote. Que pouvez-vous faire ?', '["Rien, votre vote est perdu", "Donner une procuration à une personne de confiance inscrite sur les listes électorales", "Voter par téléphone", "Envoyer votre bulletin par courrier"]'::jsonb, 1, 'Si vous ne pouvez pas vous rendre au bureau de vote, vous pouvez établir une procuration pour qu''une personne de confiance, inscrite sur les listes électorales, vote à votre place. La démarche se fait en ligne ou au commissariat/gendarmerie.', 'moyen', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('db4a2af2-a9cd-4241-bb34-f79c37c2db93', 'droits_devoirs', 'Lors d''un entretien d''embauche, on vous demande si vous êtes enceinte ou prévoyez d''avoir des enfants. Que dit la loi ?', '["C''est une question normale lors d''un entretien", "Cette question est discriminatoire et interdite par la loi", "Vous devez répondre honnêtement", "Seul l''employeur public peut poser cette question"]'::jsonb, 1, 'Les questions sur la grossesse ou les projets familiaux lors d''un entretien d''embauche constituent une discrimination fondée sur le sexe et la situation familiale, interdite par le Code du travail et le Code pénal. L''égalité entre les femmes et les hommes est un principe fondamental.', 'moyen', '2026-03-02 15:17:19.260371+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('073137b6-3461-44e3-9c4f-e6420c409237', 'vivre_societe', 'Vous conduisez en France et votre téléphone sonne. Que devez-vous faire ?', '["Répondre rapidement car l''appel peut être important", "Ne pas répondre et vous arrêter dans un endroit sûr si nécessaire, car l''usage du téléphone au volant est interdit", "Répondre en utilisant le haut-parleur", "Envoyer un SMS pour dire que vous rappelez"]'::jsonb, 1, 'L''usage du téléphone tenu en main au volant est interdit en France (amende de 135 € et retrait de 3 points). Même avec des écouteurs ou un kit mains libres, l''attention est réduite. Il faut s''arrêter en sécurité pour utiliser son téléphone.', 'facile', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('0d4042d7-beb1-4de5-b106-4c25617f5449', 'droits_devoirs', 'Vous trouvez un portefeuille contenant de l''argent et des papiers d''identité dans la rue. Que devez-vous faire ?', '["Garder l''argent et jeter le reste", "Le rapporter au commissariat de police ou à la mairie la plus proche", "Le laisser sur place, ce n''est pas votre problème", "Chercher la personne sur les réseaux sociaux"]'::jsonb, 1, 'En France, conserver un objet trouvé sans chercher à le restituer peut être qualifié de vol. Vous devez le déposer au commissariat, à la gendarmerie ou à la mairie. Si le propriétaire ne le réclame pas dans un délai légal, vous pourrez éventuellement le récupérer.', 'facile', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('10d00acb-fe88-4b72-95c3-125e98ba87c0', 'vivre_societe', 'Vous êtes convoqué(e) pour participer à un jury d''assises. Pouvez-vous refuser ?', '["Oui, c''est un choix personnel", "Non, la participation à un jury d''assises est un devoir civique obligatoire sauf motif légitime", "Oui, si vous avez un emploi", "Oui, en payant une amende"]'::jsonb, 1, 'Être juré d''assises est un devoir civique obligatoire pour tout citoyen français inscrit sur les listes électorales. Un refus sans motif légitime (maladie, âge supérieur à 70 ans, etc.) est passible d''une amende de 3 750 €.', 'difficile', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('262fd3ea-f1c0-4707-b292-bebb58064cb6', 'droits_devoirs', 'Vous recevez un courrier officiel des impôts vous demandant de déclarer vos revenus. Vous n''avez pas travaillé cette année. Que devez-vous faire ?', '["Ignorer le courrier puisque vous n''avez pas de revenus", "Remplir et envoyer votre déclaration même avec des revenus à zéro, car la déclaration est obligatoire", "Appeler les impôts pour leur dire de ne plus vous écrire", "Attendre qu''ils vous relancent"]'::jsonb, 1, 'La déclaration de revenus est obligatoire pour toute personne majeure résidant en France, même si vous n''avez perçu aucun revenu. Ne pas déclarer peut entraîner des pénalités et vous priver de certains droits (aides sociales, par exemple).', 'moyen', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('3331b1b3-971c-430a-af7e-49f4718606fe', 'droits_devoirs', 'Vous souhaitez obtenir un acte de naissance pour une démarche administrative. Où devez-vous vous adresser ?', '["À la préfecture de votre département", "À la mairie de votre lieu de naissance ou en ligne sur le site service-public.fr", "Au commissariat de police", "À votre employeur"]'::jsonb, 1, 'Les actes de naissance sont délivrés par la mairie du lieu de naissance. La demande peut aussi se faire en ligne gratuitement sur service-public.fr. C''est un document souvent demandé pour les démarches administratives (mariage, passeport, etc.).', 'facile', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('3b397474-1864-4377-aae4-8ed0bc070c68', 'vivre_societe', 'Vous voyagez dans le métro sans titre de transport valide et un contrôleur vous arrête. Que risquez-vous ?', '["Rien, le transport public est gratuit", "Une amende pouvant aller jusqu''à 375 € en cas de non-régularisation", "Un simple avertissement sans conséquence", "Une interdiction de voyager pendant un mois"]'::jsonb, 1, 'Voyager sans titre de transport valide constitue une infraction. L''amende forfaitaire est généralement de 50 € si payée immédiatement, mais peut atteindre 375 € en cas de non-paiement. Il est obligatoire de posséder un titre de transport valide.', 'facile', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('3bcee972-021d-4e44-84da-4d93d4f91881', 'vivre_societe', 'Vous déménagez dans une nouvelle ville. Quelles démarches devez-vous effectuer ?', '["Aucune, votre ancienne adresse reste valable", "Signaler votre changement d''adresse aux administrations (impôts, Assurance maladie, CAF) et mettre à jour votre carte grise dans les 30 jours", "Attendre le prochain renouvellement de papiers", "Prévenir uniquement votre banque"]'::jsonb, 1, 'Lors d''un déménagement, vous devez signaler votre nouvelle adresse à plusieurs organismes : les impôts, l''Assurance maladie, la CAF, et mettre à jour votre carte grise sous 30 jours. Le service en ligne service-public.fr permet de faire un changement d''adresse groupé.', 'moyen', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('638c6477-1a08-42b5-a470-126ba0a76692', 'vivre_societe', 'Vous assistez à un accident de la route. Personne ne semble blessé gravement, mais les véhicules bloquent la circulation. Que devez-vous faire ?', '["Continuer votre route sans vous arrêter", "Vous arrêter en sécurité, vérifier l''état des personnes, appeler le 15 ou le 112 si nécessaire, et sécuriser les lieux", "Prendre des photos et les publier sur les réseaux sociaux", "Klaxonner pour que les conducteurs dégagent la route"]'::jsonb, 1, 'En France, la non-assistance à personne en danger est un délit puni par la loi (jusqu''à 5 ans d''emprisonnement et 75 000 € d''amende). Vous devez vous arrêter en sécurité, porter assistance et alerter les secours si nécessaire.', 'moyen', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('88a831ba-683f-413f-87da-c229f0d0591c', 'vivre_societe', 'Un ami vous propose de lui donner vos médicaments sur ordonnance car il a les mêmes symptômes. Que devez-vous faire ?', '["Accepter pour lui rendre service", "Refuser car les médicaments sur ordonnance sont personnels et ne doivent pas être partagés", "Accepter seulement si c''est le même médecin", "Lui donner la moitié de votre traitement"]'::jsonb, 1, 'Les médicaments prescrits sur ordonnance sont adaptés à chaque patient en fonction de son état de santé, son poids, ses allergies et ses autres traitements. Les partager est dangereux et interdit. Votre ami doit consulter un médecin.', 'facile', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('95778006-0ce4-435a-ba45-1a18534562ec', 'vivre_societe', 'Vous êtes malade et devez consulter un médecin, mais vous n''avez pas de médecin traitant. Que devez-vous faire ?', '["Aller directement aux urgences de l''hôpital", "Chercher un médecin généraliste acceptant de nouveaux patients et le déclarer comme médecin traitant auprès de l''Assurance maladie", "Acheter des médicaments directement en pharmacie sans ordonnance", "Attendre que la maladie passe"]'::jsonb, 1, 'En France, il est recommandé de déclarer un médecin traitant auprès de l''Assurance maladie. Cela permet un meilleur suivi médical et un meilleur remboursement des soins. Sans médecin traitant, le remboursement est réduit.', 'facile', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('abdbeff4-7c6e-41ab-b26f-9f0a32013bef', 'vivre_societe', 'Vous venez d''arriver en France et vous n''avez pas encore de couverture santé. Que devez-vous faire ?', '["Payer tous vos soins de votre poche", "Demander la Protection Universelle Maladie (PUMa) ou l''Aide Médicale de l''État (AME) selon votre situation", "Retourner dans votre pays d''origine pour vous soigner", "Aller uniquement aux urgences car c''est gratuit"]'::jsonb, 1, 'En France, toute personne résidant de manière stable et régulière a droit à la Protection Universelle Maladie (PUMa). Les personnes en situation irrégulière peuvent bénéficier de l''Aide Médicale de l''État (AME). L''accès aux soins est un droit fondamental.', 'moyen', '2026-03-02 15:23:27.799985+00');
INSERT INTO public.questions (id, theme, question, options, correct_answer, explanation, difficulty, created_at) VALUES ('b7c5f11e-f887-4f1c-8837-e645bb6ba8c0', 'vivre_societe', 'Votre enfant se blesse gravement au parc un dimanche. Quel numéro devez-vous appeler en priorité ?', '["Le 12", "Le 15 (SAMU) ou le 112 (numéro d''urgence européen)", "Le 17 (police)", "Votre médecin traitant"]'::jsonb, 1, 'En cas d''urgence médicale, il faut appeler le 15 (SAMU) ou le 112 (numéro d''urgence européen, accessible partout en Europe). Le 15 permet d''être orienté vers les secours adaptés. Le 112 fonctionne même sans réseau téléphonique national.', 'facile', '2026-03-02 15:23:27.799985+00');
